add_filter( 'woocommerce_available_payment_gateways', 'perfectpixel_gateway_by_billing_country' );

function perfectpixel_gateway_by_billing_country( $gateways ) {
	if ( is_admin() || ! WC()->customer ) {
		return $gateways;
	}
	// Gateway ID => countries where it is shown (hidden everywhere else).
	$only_in = array(
		'cod' => array( 'GR', 'CY' ),
	);
	// Gateway ID => countries where it is hidden.
	$hide_in = array(
		// 'bacs' => array( 'US' ),
	);

	$country = WC()->customer->get_billing_country();
	foreach ( $only_in as $id => $countries ) {
		if ( $country && ! in_array( $country, $countries, true ) ) {
			unset( $gateways[ $id ] );
		}
	}
	foreach ( $hide_in as $id => $countries ) {
		if ( in_array( $country, $countries, true ) ) {
			unset( $gateways[ $id ] );
		}
	}
	return $gateways;
}
